import { mkdir, writeFile } from "node:fs/promises";
import { dirname } from "node:path";
import { fileURLToPath } from "node:url";

import openapiTS, { astToString, type OpenAPI3 } from "openapi-typescript";

const API_INTERNAL_URL = process.env.API_INTERNAL_URL ?? "http://localhost:8000";
const specUrl = `${API_INTERNAL_URL.replace(/\/+$/, "")}/openapi.json`;
const outputPath = fileURLToPath(
  new URL("../src/lib/api/types.ts", import.meta.url),
);
const generatedHeader = [
  "/**",
  " * This file was auto-generated by `npm run api:types` from the FastAPI OpenAPI spec.",
  " * Do not make direct changes to the file.",
  " */",
  "/* eslint-disable */",
  "",
  "",
].join("\n");

function fail(message: string): void {
  console.error(`[api:types] ${message}`);
  process.exitCode = 1;
}

async function main(): Promise<void> {
  let spec: unknown;

  try {
    const response = await fetch(specUrl);
    if (!response.ok) {
      fail(
        `could not read ${specUrl}: HTTP ${response.status} ${response.statusText}`,
      );
      return;
    }
    spec = await response.json();
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    fail(`could not reach the API at ${specUrl}: ${reason}`);
    console.error(
      "[api:types] start the API with `docker compose up -d api` or set API_INTERNAL_URL.",
    );
    return;
  }

  if (
    typeof spec !== "object" ||
    spec === null ||
    !("openapi" in spec) ||
    typeof spec.openapi !== "string"
  ) {
    fail(`${specUrl} did not return an OpenAPI document.`);
    return;
  }

  try {
    const ast = await openapiTS(spec as OpenAPI3);
    const types = astToString(ast);
    await mkdir(dirname(outputPath), { recursive: true });
    await writeFile(outputPath, generatedHeader + types, "utf8");
    console.log(`[api:types] wrote ${outputPath}`);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    fail(`could not generate types from ${specUrl}: ${reason}`);
  }
}

await main();
